use std::{collections::{BTreeMap,BTreeSet},fs,io::Write};
fn main(){let root="research/hec_residual_span_20261116/incidence-oracle";let mut blocks=BTreeMap::<(usize,usize,usize),(usize,Vec<usize>)>::new();let mut totals=BTreeMap::<(usize,usize),(usize,usize,Vec<usize>)>::new();for l in fs::read_to_string(format!("{root}/ROOTS.tsv")).unwrap().lines().skip(1){let v:Vec<_>=l.split('\t').collect();assert_eq!(v.len(),6);let n=|j:usize|v[j].parse::<usize>().unwrap();let(r,a)=(n(2),n(3));assert!((1..=16).contains(&a));let roots:Vec<_>=v[5].split(',').collect();assert_eq!(roots.len(),3);let set:BTreeSet<usize>=roots.iter().map(|x|x.split(':').next().unwrap().parse().unwrap()).collect();let b=blocks.entry((n(0),n(1),a)).or_insert((0,vec![0;r]));b.0+=1;let total=totals.entry((n(0),n(1))).or_insert((0,r,vec![0;r]));total.0+=1;assert_eq!(total.1,r);for j in set{assert!(j<r);b.1[j]+=1;total.2[j]+=1;}}
assert_eq!(totals.len(),6);let mut out=fs::File::create_new(format!("{root}/ADAPTIVE-BLOCKS.tsv")).unwrap();writeln!(out,"p\tsm\tanchor\torbit\trows_in_anchor\trows_hit\tfull_panel_relative_rate").unwrap();println!("p\tsm\trows\tcolumns\tbest_fixed_single_orbit_rate\tbest_free_anchor_orbit_rate\tbest_anchor\tbest_orbit\tbest_rows_hit");for(&(p,sm),(m,r,degree))in &totals{let mut best=(0,0,0);let mut counted=0;for a in 1..=16{if let Some((ma,d))=blocks.get(&(p,sm,a)){counted+=ma;assert!(d.iter().all(|x|x<=ma));for(j,&v)in d.iter().enumerate(){let rate=(16*r*v)as f64/ *m as f64;writeln!(out,"{p}\t{sm}\t{a}\t{j}\t{ma}\t{v}\t{rate:.9}").unwrap();if v>best.0{best=(v,a,j);}}}else{for j in 0..*r{writeln!(out,"{p}\t{sm}\t{a}\t{j}\t0\t0\t0.000000000").unwrap();}}}assert_eq!(counted,*m);let fixed=(*r*degree.iter().max().unwrap())as f64/ *m as f64;let adaptive=(16*r*best.0)as f64/ *m as f64;println!("{p}\t{sm}\t{m}\t{r}\t{fixed:.9}\t{adaptive:.9}\t{}\t{}\t{}",best.1,best.2,best.0);}eprintln!("workloads=6 all_16_anchor_orbit_blocks=true row_coverage_deduplicated=true no_producer_rerun=true");}
